/* medicine-data.js — entries of the Medicine & Disease Atlas (medicine-atlas.html).
 * A history of medicine for learning — not medical advice. */
(function () {
  const M = (i, color, extra) => ['med', Object.assign({ i, color }, extra || {})];
  window.MEDICINE_CATS = {
    disease: ['Plagues & pandemics', '#7b1f16', '🦠'],
    vaccine: ['Vaccines', '#2a8fa3', '💉'],
    drug: ['Medicines', '#c9922a', '💊'],
    science: ['Discoveries', '#8a6cc0', '🔬'],
    tools: ['Tools for diagnosis & care', '#4f7598', '🩻'],
    health: ['Public health', '#2e7d32', '🚰']
  };
  window.MEDICINE_ERAS = [
    { n: 'Ancient medicine', to: 500, range: 'before 500 CE', intro: 'Healers in Egypt, Mesopotamia, India, China and Greece used plants, diet and careful observation. Most believed illness came from gods, spirits or an imbalance in the body.' },
    { n: 'Medieval medicine', to: 1500, range: '500 – 1500', intro: 'Doctors of the Islamic world built hospitals and wrote great textbooks. Plagues such as the Black Death killed huge numbers, and cities invented quarantine.' },
    { n: 'The scientific revolution', to: 1800, range: '1500 – 1800', intro: 'Dissection, microscopes and experiments replaced ancient authority. The first controlled trial and the first vaccine appeared.' },
    { n: 'The germ revolution', to: 1900, range: '1800 – 1900', intro: 'Scientists proved that germs cause disease. Clean water, sewers, nursing and anaesthesia saved millions of lives.' },
    { n: 'Wonder drugs', to: 1950, range: '1900 – 1949', intro: 'Insulin, penicillin, sulfa drugs and new vaccines turned deadly diseases into treatable ones — while Spanish flu killed tens of millions.' },
    { n: 'Modern medicine', to: 2000, range: '1950 – 1999', intro: 'Mass vaccination eradicated smallpox. Scanners looked inside the body, and new drugs treated cancer, HIV and mental illness.' },
    { n: 'Medicine today', to: 99999, range: '2000 – today', intro: 'Genome sequencing, targeted cancer drugs, gene editing and mRNA vaccines — and new pandemics such as SARS and COVID-19.' }
  ];
  window.MEDICINES = [
    // ---------------- ancient
    { id: 'malaria', n: 'Malaria', c: 'disease', y: -2700, d: 'Ancient (described c. 2700 BCE)', r: 'Tropical and warm regions worldwide', w: 'Parasite found by Alphonse Laveran (1880); mosquito link by Ronald Ross (1897)', s: 'A disease of fever and chills caused by a tiny parasite spread by mosquitoes. It may have killed more people than any other disease in history.', how: 'Female Anopheles mosquitoes pass Plasmodium parasites into the blood. They multiply in the liver and red blood cells.', impact: 'Still kills about 600,000 people a year, mostly young children in Africa. Bed nets, drugs and new vaccines are cutting deaths.', f: 'Its name comes from Italian mal’aria, “bad air”, because people blamed swamp air.', p: M('mosquito'), x: ['quinine', 'artemisinin', 'malaria-vaccine'] },
    { id: 'smallpox', n: 'Smallpox', c: 'disease', y: -1145, d: 'by 1145 BCE', r: 'Worldwide', w: 'Variola virus', s: 'A deadly virus that caused fever and a rash of blisters, killing about 3 in 10 people who caught it and scarring many survivors.', how: 'It spread through the air and on objects from person to person. Survivors were immune for life.', impact: 'It killed about 300 million people in the 20th century alone. Brought by Europeans, it devastated the peoples of the Americas from 1520.', f: 'The mummy of Pharaoh Ramses V, who died in 1145 BCE, shows smallpox scars.', p: M('virus', '#a0522d'), x: ['variolation', 'smallpox-vaccine', 'smallpox-eradication'] },
    { id: 'huangdi-neijing', n: 'The Yellow Emperor’s Classic of Medicine', c: 'science', y: -200, d: 'c. 2nd century BCE', r: 'China', w: 'Unknown authors, named after the legendary Yellow Emperor', s: 'The founding book of traditional Chinese medicine, describing the body, qi, yin and yang, and acupuncture.', how: 'It explains health as balance and harmony, using observation of the pulse, tongue and season.', impact: 'Still studied in traditional Chinese medicine today.', f: 'It is written as a conversation between the emperor and his doctors.', p: M('book'), x: ['hippocrates'] },
    { id: 'hippocrates', n: 'Hippocrates and the four humours', c: 'science', y: -400, d: 'c. 400 BCE', r: 'Kos, Greece', w: 'Hippocrates and his school', s: 'Greek doctors who taught that diseases have natural causes, not divine ones, and that doctors must observe and record carefully.', how: 'They thought health was a balance of four “humours”: blood, phlegm, yellow bile and black bile. That idea was wrong but lasted 2,000 years.', impact: 'The Hippocratic Oath shaped medical ethics: help the sick and do no harm.', f: 'Bloodletting to “rebalance the humours” was done until the 1800s — and usually did harm.', p: M('book'), x: ['galen-anatomy', 'ibn-sina', ['surgery-atlas.html#hippocratic-surgery', 'Greek surgery']] },
    { id: 'plague-athens', n: 'Plague of Athens', c: 'disease', y: -430, d: '430 BCE', r: 'Athens, Greece', w: 'Described by Thucydides', s: 'An epidemic that killed perhaps a quarter of Athens during its war with Sparta, including the leader Pericles.', how: 'Crowds of refugees inside the city walls helped it spread. Its cause is still debated — perhaps typhoid or typhus.', impact: 'It weakened Athens, which went on to lose the Peloponnesian War.', f: 'Thucydides caught it, survived, and noticed survivors did not get it again — an early observation of immunity.', p: M('virus', '#8a6a4a'), x: ['antonine-plague'] },
    { id: 'galen-anatomy', n: 'Galen’s medicine', c: 'science', y: 170, d: 'c. 170 CE', r: 'Roman Empire', w: 'Galen of Pergamon', s: 'Galen wrote hundreds of books joining Greek theory with his own experiments on animals. His ideas ruled medicine for 1,400 years.', how: 'He tested ideas by experiment — for example, cutting nerves in pigs to show the brain controls the voice.', impact: 'His mistakes, such as blood being made in the liver and passing through holes in the heart, were finally corrected by Vesalius and Harvey.', f: 'He was doctor to the gladiators and to Emperor Marcus Aurelius.', p: M('book'), x: ['vesalius', 'harvey-circulation', ['surgery-atlas.html#galen', 'Galen in the Surgery Atlas']] },
    { id: 'antonine-plague', n: 'Antonine Plague', c: 'disease', y: 165, d: '165 CE', r: 'Roman Empire', w: 'Described by Galen', s: 'An epidemic, probably smallpox, brought back by soldiers returning from the east. It killed millions across the Roman Empire.', how: 'Armies and trade routes spread it from city to city.', impact: 'It may have killed up to 10% of the empire’s people and weakened its armies.', f: 'Emperor Lucius Verus may have died of it.', p: M('virus', '#a0522d'), x: ['smallpox', 'justinian-plague'] },
    // ---------------- medieval
    { id: 'justinian-plague', n: 'Plague of Justinian', c: 'disease', y: 541, d: '541', r: 'Byzantine Empire and Mediterranean', w: 'Yersinia pestis bacterium', s: 'The first known pandemic of bubonic plague, which killed perhaps tens of millions around the Mediterranean.', how: 'Fleas on rats carried the bacteria along trade routes and grain ships.', impact: 'It returned in waves for 200 years and weakened the Byzantine Empire.', f: 'DNA from 6th-century graves in Germany proved it was the same bacterium as the Black Death.', p: M('rat'), x: ['black-death'] },
    { id: 'bimaristan', n: 'Bimaristans (public hospitals)', c: 'health', y: 805, d: 'c. 805', r: 'Baghdad, then Cairo, Damascus and beyond', w: 'Abbasid rulers and doctors', s: 'Large hospitals of the Islamic world that treated everyone, rich or poor, with wards, pharmacies and libraries.', how: 'Separate wards for different illnesses, trained doctors and nurses, and free care paid for by charity.', impact: 'They were also teaching hospitals, where students learned at the bedside.', f: 'The Al-Mansuri hospital in Cairo (1284) had music to soothe patients.', p: M('hospital', '#2e7d32'), x: ['ibn-sina'] },
    { id: 'measles', n: 'Measles', c: 'disease', y: 910, d: 'c. 910 (first clear description)', r: 'Baghdad', w: 'Described by Abu Bakr al-Razi (Rhazes)', s: 'One of the most contagious viruses, causing fever, cough and a rash. Al-Razi was the first to tell it apart from smallpox.', how: 'It spreads through the air; one person can infect 12–18 others.', impact: 'Before vaccines it killed about 2.6 million people a year.', f: 'Measles can wipe the immune system’s “memory” of other diseases.', p: M('virus', '#c0392b'), x: ['measles-vaccine', 'smallpox'] },
    { id: 'ibn-sina', n: 'Ibn Sina’s Canon of Medicine', c: 'science', y: 1025, d: '1025', r: 'Persia', w: 'Ibn Sina (Avicenna)', s: 'A vast medical encyclopaedia that was the standard textbook in the Islamic world and Europe for 600 years.', how: 'It set rules for testing medicines, described contagion and quarantine, and listed hundreds of drugs.', impact: 'Taught in European universities until the 1600s.', f: 'Ibn Sina is said to have learned the whole Quran by heart by the age of 10.', p: M('book'), x: ['ibn-al-nafis', 'bimaristan'] },
    { id: 'ibn-al-nafis', n: 'Ibn al-Nafis and lung circulation', c: 'science', y: 1242, d: '1242', r: 'Cairo, Egypt', w: 'Ibn al-Nafis', s: 'He described how blood travels from the heart to the lungs and back — 300 years before Europe.', how: 'He reasoned that blood cannot pass through the heart’s thick middle wall, as Galen said, and must pass through the lungs.', impact: 'His work was forgotten until 1924, when his manuscript was found in Berlin.', f: 'He wrote a whole medical encyclopaedia and a novel.', p: M('lungs'), x: ['harvey-circulation', 'galen-anatomy'] },
    { id: 'black-death', n: 'Black Death', c: 'disease', y: 1347, d: '1347', r: 'Asia, Europe, North Africa', w: 'Yersinia pestis bacterium', s: 'The deadliest pandemic in recorded history: bubonic plague killed perhaps a third to half of Europe’s people in a few years.', how: 'Fleas carried it; the lung form (pneumonic plague) spread directly between people.', impact: 'It changed society: workers became scarce and wages rose. Cities invented quarantine.', f: 'Plague still exists and is treated with antibiotics; a few thousand cases occur each year.', p: M('rat'), x: ['quarantine', 'justinian-plague'] },
    { id: 'quarantine', n: 'Quarantine', c: 'health', y: 1377, d: '1377', r: 'Ragusa (Dubrovnik, Croatia)', w: 'City council of Ragusa', s: 'Ships and travellers from plague areas had to wait in isolation before entering the city.', how: 'Isolating people who may be infected until it is clear they are not stops a disease from spreading.', impact: 'Used against plague, cholera, yellow fever and COVID-19.', f: 'Venice later set 40 days — quaranta giorni in Italian — giving us the word.', p: M('cross', '#2e7d32'), x: ['black-death', 'covid-19'] },
    // ---------------- 1500–1800
    { id: 'syphilis', n: 'Syphilis', c: 'disease', y: 1495, d: '1495', r: 'Naples, then all Europe', w: 'Treponema pallidum bacterium', s: 'A sexually transmitted infection that spread through Europe after 1495, at first in a very severe form.', how: 'Spread through sexual contact. Untreated, it can damage the heart, brain and nerves after many years.', impact: 'Treatments with mercury were toxic. Salvarsan (1910) and then penicillin cured it.', f: 'Every country blamed another: the French called it the Italian disease, the Italians the French disease.', p: M('bacteria', '#8a6cc0'), x: ['salvarsan', 'penicillin'] },
    { id: 'vesalius', n: 'Vesalius and human anatomy', c: 'science', y: 1543, d: '1543', r: 'Padua, Italy', w: 'Andreas Vesalius', s: 'His book De humani corporis fabrica showed the human body accurately from his own dissections, with stunning drawings.', how: 'He did the dissections himself instead of reading Galen aloud while an assistant cut.', impact: 'He corrected over 200 of Galen’s mistakes and founded modern anatomy.', f: 'Copernicus’s book putting the Sun at the centre came out in the same year.', p: M('book'), x: ['galen-anatomy', 'harvey-circulation', ['space-atlas.html#copernicus', 'Copernicus']] },
    { id: 'variolation', n: 'Variolation', c: 'vaccine', y: 1550, d: '16th century (China); 1721 in Britain and America', r: 'China, India, Africa, Ottoman Empire', w: 'Folk healers; brought to Britain by Lady Mary Wortley Montagu and to Boston by Onesimus', s: 'Deliberately giving a mild smallpox infection from a sufferer’s scabs or pus to protect against severe smallpox.', how: 'Infection through the skin or nose was usually milder than catching it naturally, and gave lifelong immunity.', impact: 'About 1–2% died from it, far fewer than the 30% from natural smallpox. It paved the way for vaccines.', f: 'Onesimus, an enslaved African man in Boston, explained the method to Cotton Mather in 1721.', p: M('syringe', '#a0522d', { fill: 20 }), x: ['smallpox-vaccine', 'smallpox'] },
    { id: 'harvey-circulation', n: 'Circulation of the blood', c: 'science', y: 1628, d: '1628', r: 'England', w: 'William Harvey', s: 'Harvey proved that the heart pumps blood around the body in a circuit, through arteries and back through veins.', how: 'He measured how much blood the heart pumped — far more than food could make — so it must go round and round.', impact: 'It overturned 1,400 years of Galen’s teaching and opened the way to modern physiology.', f: 'Harvey could not see capillaries; Marcello Malpighi found them with a microscope in 1661.', p: M('heart'), x: ['ibn-al-nafis', 'vesalius'] },
    { id: 'leeuwenhoek', n: 'Microbes seen for the first time', c: 'science', y: 1676, d: '1676', r: 'Delft, Netherlands', w: 'Antonie van Leeuwenhoek', s: 'A cloth merchant who made tiny, powerful microscopes and was the first to see bacteria, which he called “animalcules”.', how: 'His single-lens microscopes magnified about 270 times — better than any of his time.', impact: 'It took 200 years before scientists proved that such microbes cause disease.', f: 'He found bacteria in the plaque on his own teeth.', p: M('microscope', '#c0392b'), x: ['germ-theory', 'viruses-discovered'] },
    { id: 'scurvy-trial', n: 'Lind’s scurvy trial', c: 'science', y: 1747, d: '1747', r: 'HMS Salisbury, at sea', w: 'James Lind', s: 'Lind gave 12 sailors with scurvy six different treatments; the two given oranges and lemons recovered fast.', how: 'Comparing treatments side by side in similar patients is a “controlled trial”.', impact: 'Scurvy is caused by lack of vitamin C. The British navy gave sailors lemon juice from 1795.', f: 'British sailors were nicknamed “limeys” because of the citrus juice.', p: M('herb', '#e2a63b', { flower: 1 }), x: ['vitamins', 'controlled-trial'] },
    { id: 'digitalis', n: 'Digitalis (foxglove)', c: 'drug', y: 1785, d: '1785', r: 'England', w: 'William Withering', s: 'A medicine from the foxglove plant that strengthens a failing heartbeat.', how: 'It makes the heart muscle squeeze more strongly and slows a fast heart rate.', impact: 'Digoxin, made from foxglove, is still used.', f: 'Withering learned of it from a folk healer’s secret recipe of 20 herbs.', p: M('herb', '#8a6cc0', { flower: 1 }), x: ['quinine'] },
    { id: 'smallpox-vaccine', n: 'Smallpox vaccine', c: 'vaccine', y: 1796, d: '1796', r: 'Berkeley, England', w: 'Edward Jenner', s: 'Jenner gave 8-year-old James Phipps cowpox, a mild disease, and showed it protected him against smallpox — the first vaccine.', how: 'Cowpox is similar enough to smallpox that the immune system learns to fight both.', impact: 'It led to the complete eradication of smallpox in 1980.', f: '“Vaccine” comes from vacca, Latin for cow.', p: M('syringe', '#2a8fa3'), x: ['variolation', 'smallpox-eradication', 'rabies-vaccine'] },
    { id: 'yellow-fever', n: 'Yellow fever', c: 'disease', y: 1793, d: '1793 (Philadelphia epidemic)', r: 'Africa and the Americas', w: 'Mosquito spread shown by Carlos Finlay and Walter Reed (1900)', s: 'A virus spread by mosquitoes that causes fever, bleeding and yellow skin (jaundice).', how: 'Aedes aegypti mosquitoes carry it between people.', impact: 'It killed a tenth of Philadelphia in 1793 and stopped the French from building the Panama Canal.', f: 'Controlling mosquitoes let the USA finish the Panama Canal in 1914.', p: M('mosquito'), x: ['yellow-fever-vaccine'] },
    // ---------------- 1800–1900
    { id: 'morphine', n: 'Morphine', c: 'drug', y: 1804, d: '1804', r: 'Germany', w: 'Friedrich Sertürner', s: 'The main pain-killing substance in opium, purified for the first time — the first drug ever taken from a plant in pure form.', how: 'It acts on opioid receptors in the brain and spinal cord to block pain.', impact: 'Vital for severe pain, but very addictive. Opioid addiction remains a major problem.', f: 'Sertürner named it after Morpheus, the Greek god of dreams.', p: M('vial', '#8a6cc0'), x: ['aspirin'] },
    { id: 'stethoscope', n: 'Stethoscope', c: 'tools', y: 1816, d: '1816', r: 'Paris, France', w: 'René Laennec', s: 'A tube for listening to the heart and lungs. Laennec’s first was a rolled-up paper.', how: 'Sound travels well along a tube, so doctors could hear heartbeats and breathing clearly.', impact: 'Laennec matched the sounds with diseases found after death, founding diagnosis by listening.', f: 'He invented it because he was embarrassed to put his ear to a young woman’s chest.', p: M('stethoscope'), x: ['ecg', 'thermometer'] },
    { id: 'cholera', n: 'Cholera pandemics', c: 'disease', y: 1817, d: '1817', r: 'From Bengal across the world', w: 'Vibrio cholerae bacterium', s: 'A bacterial infection of the gut that causes severe diarrhoea and can kill within hours.', how: 'It spreads through water and food dirty with sewage.', impact: 'Seven pandemics since 1817 killed millions and drove cities to build sewers and clean water.', f: 'Oral rehydration solution — clean water, salt and sugar — can save almost every patient.', p: M('bacteria', '#2a8fa3'), x: ['john-snow', 'sewers', 'ors'] },
    { id: 'quinine', n: 'Quinine', c: 'drug', y: 1820, d: '1820', r: 'Paris, France (from South American bark)', w: 'Pierre Pelletier and Joseph Caventou; cinchona known to the Quechua', s: 'The first effective malaria medicine, purified from the bark of the cinchona tree.', how: 'It kills the malaria parasite inside red blood cells.', impact: 'It let Europeans survive in malaria regions — sadly also helping colonial conquest.', f: 'Tonic water contains quinine; the British in India mixed it with gin.', p: M('herb', '#a0522d'), x: ['malaria', 'artemisinin'] },
    { id: 'semmelweis', n: 'Handwashing (Semmelweis)', c: 'health', y: 1847, d: '1847', r: 'Vienna, Austria', w: 'Ignaz Semmelweis', s: 'Semmelweis made doctors wash their hands in chlorine solution, and deaths of new mothers from childbed fever fell from about 10% to 1%.', how: 'Doctors carried germs from dissections to women giving birth. Washing removed them.', impact: 'Many doctors rejected his idea at the time; germ theory later proved him right.', f: 'He died in an asylum in 1865, his work not yet accepted.', p: M('water', '#2e7d32'), x: ['germ-theory', ['surgery-atlas.html#antisepsis', 'Antiseptic surgery']] },
    { id: 'john-snow', n: 'John Snow and the Broad Street pump', c: 'health', y: 1854, d: '1854', r: 'London, UK', w: 'John Snow', s: 'By mapping cholera deaths, Snow showed they clustered around one water pump, and the outbreak ended after the pump handle was removed.', how: 'Comparing who got sick and where they lived — epidemiology — pointed to dirty water, not “bad air”.', impact: 'He founded modern epidemiology and pushed cities towards clean water.', f: 'A replica of the pump without its handle stands in Broadwick Street, London.', p: M('water', '#2a8fa3'), x: ['cholera', 'sewers'] },
    { id: 'nightingale', n: 'Florence Nightingale and modern nursing', c: 'health', y: 1854, d: '1854', r: 'Scutari (Istanbul) and London', w: 'Florence Nightingale', s: 'In the Crimean War, Nightingale and her nurses cleaned up a filthy army hospital, and deaths fell sharply.', how: 'Hygiene, fresh air, good food and careful records.', impact: 'She founded the first professional nursing school (1860) and used statistics and charts to change government policy.', f: 'Her “rose diagrams” are among the most famous charts in history.', p: M('nurse'), x: ['mary-seacole', 'red-cross'] },
    { id: 'mary-seacole', n: 'Mary Seacole', c: 'health', y: 1855, d: '1855', r: 'Jamaica and the Crimea', w: 'Mary Seacole', s: 'A Jamaican-Scottish nurse who paid her own way to the Crimean War and ran the “British Hotel”, caring for soldiers near the front.', how: 'She used skills learned from her mother, a Jamaican healer, treating cholera and wounds.', impact: 'Hugely popular with soldiers, she was forgotten for a century and is now celebrated as a pioneer.', f: 'In 2004 she was voted the greatest Black Briton.', p: M('nurse'), x: ['nightingale'] },
    { id: 'sewers', n: 'Sewers and clean water', c: 'health', y: 1858, d: '1858', r: 'London, UK', w: 'Joseph Bazalgette', s: 'After the “Great Stink” of 1858, London built huge brick sewers that carried waste away from the river where people got water.', how: 'Sewage was carried downstream away from drinking water, stopping cholera and typhoid.', impact: 'Clean water and sewers saved more lives than any medicine of the 1800s.', f: 'Bazalgette made the pipes twice as big as needed — so they still work today.', p: M('sewer'), x: ['john-snow', 'chlorination'] },
    { id: 'germ-theory', n: 'Germ theory', c: 'science', y: 1861, d: '1861–1882', r: 'France and Germany', w: 'Louis Pasteur and Robert Koch', s: 'Pasteur and Koch proved that tiny living germs cause infectious diseases.', how: 'Pasteur showed microbes do not appear from nothing; Koch found the germs of anthrax (1876), tuberculosis (1882) and cholera (1883).', impact: 'It led to antiseptic surgery, vaccines, clean water and antibiotics.', f: 'Koch’s rules for proving a germ causes a disease are still taught as Koch’s postulates.', p: M('bacteria', '#4e9e73'), x: ['leeuwenhoek', 'tuberculosis', ['surgery-atlas.html#antisepsis', 'Antiseptic surgery']] },
    { id: 'red-cross', n: 'The Red Cross', c: 'health', y: 1863, d: '1863', r: 'Geneva, Switzerland', w: 'Henry Dunant', s: 'An international movement to help wounded soldiers and, later, all victims of war and disaster.', how: 'Medical staff under the red cross or red crescent emblem must be protected by all sides (Geneva Conventions, 1864).', impact: 'Today it has about 16 million volunteers.', f: 'Dunant was inspired by the suffering he saw after the Battle of Solferino (1859) and won the first Nobel Peace Prize.', p: M('cross', '#c0392b'), x: ['nightingale', ['surgery-atlas.html#triage', 'Triage']] },
    { id: 'thermometer', n: 'Clinical thermometer', c: 'tools', y: 1867, d: '1867', r: 'Leeds, UK', w: 'Thomas Clifford Allbutt', s: 'A short thermometer that took a temperature in five minutes instead of twenty.', how: 'Mercury or alcohol expands as it warms; a narrow neck keeps the reading until it is shaken down.', impact: 'Taking a temperature became routine for every patient.', f: 'Early thermometers were 30 cm long and took 20 minutes.', p: M('thermometer'), x: ['stethoscope'] },
    { id: 'leprosy', n: 'Leprosy (Hansen’s disease)', c: 'disease', y: 1873, d: 'Ancient; cause found 1873', r: 'Worldwide', w: 'Gerhard Armauer Hansen', s: 'A slow bacterial infection of the skin and nerves. Hansen found its cause, the first bacterium linked to a human disease.', how: 'It spreads only with long close contact; most people are naturally immune.', impact: 'People with leprosy were feared and isolated for centuries. Multi-drug treatment since 1981 cures it.', f: 'Armadillos can carry it.', p: M('bacteria', '#a0522d'), x: ['germ-theory'] },
    { id: 'tuberculosis', n: 'Tuberculosis', c: 'disease', y: 1882, d: 'Ancient; cause found 1882', r: 'Worldwide', w: 'Robert Koch', s: 'A bacterial infection, mostly of the lungs, called “consumption” or “the white plague”.', how: 'It spreads through the air when a sick person coughs.', impact: 'In the 1800s it caused about a quarter of deaths in Europe. Antibiotics cure it, but it still kills over a million people a year.', f: '24 March, the day Koch announced his discovery, is World Tuberculosis Day.', p: M('bacteria', '#8a6a4a'), x: ['bcg', 'streptomycin', 'germ-theory'] },
    { id: 'rabies-vaccine', n: 'Rabies vaccine', c: 'vaccine', y: 1885, d: '1885', r: 'Paris, France', w: 'Louis Pasteur and Émile Roux', s: 'Pasteur treated 9-year-old Joseph Meister, bitten by a rabid dog, with a weakened virus. He survived.', how: 'Rabies moves slowly to the brain, so a vaccine given soon after a bite has time to work.', impact: 'Rabies is almost always fatal once symptoms start, but vaccines after a bite prevent it.', f: 'Joseph Meister later worked as caretaker of the Pasteur Institute.', p: M('syringe', '#2a8fa3'), x: ['smallpox-vaccine', 'germ-theory'] },
    { id: 'diphtheria-antitoxin', n: 'Diphtheria antitoxin', c: 'vaccine', y: 1890, d: '1890', r: 'Berlin, Germany', w: 'Emil von Behring and Kitasato Shibasaburō', s: 'Blood serum from immunised horses that neutralised the diphtheria toxin and saved children’s lives.', how: 'Antibodies in the serum bind and disable the poison the bacteria make.', impact: 'Behring won the first Nobel Prize in Medicine (1901). Vaccines later prevented diphtheria altogether.', f: 'In 1925 dog-sled teams relayed antitoxin 1,000 km to Nome, Alaska — the lead dog Balto became famous.', p: M('vial', '#2a8fa3'), x: ['antibody-drugs'] },
    { id: 'viruses-discovered', n: 'Viruses discovered', c: 'science', y: 1892, d: '1892–1898', r: 'Russia and the Netherlands', w: 'Dmitri Ivanovsky and Martinus Beijerinck', s: 'Something smaller than bacteria passed through the finest filters and still caused disease in tobacco plants.', how: 'Beijerinck called it a “virus” — a living liquid. Electron microscopes first showed viruses in the 1930s.', impact: 'It explained diseases such as flu, measles, polio and smallpox.', f: 'Viruses cannot reproduce on their own — they hijack living cells.', p: M('virus', '#8a6cc0'), x: ['leeuwenhoek'] },
    { id: 'x-rays', n: 'X-rays', c: 'tools', y: 1895, d: '1895', r: 'Würzburg, Germany', w: 'Wilhelm Röntgen', s: 'Invisible rays that pass through flesh but not bone, letting doctors see inside the body without cutting.', how: 'Dense tissue like bone blocks X-rays, leaving a white shadow on the film.', impact: 'Within months X-rays were used across the world. Marie Curie drove mobile X-ray vans in WWI.', f: 'Early users did not know about radiation dangers; some shoe shops X-rayed feet until the 1950s.', p: M('xray'), x: ['ct-scan', ['surgery-atlas.html#x-rays', 'X-rays in surgery']] },
    { id: 'blood-pressure', n: 'Blood pressure cuff', c: 'tools', y: 1896, d: '1896', r: 'Italy', w: 'Scipione Riva-Rocci; sounds by Nikolai Korotkov (1905)', s: 'An inflatable cuff and a gauge to measure blood pressure without cutting.', how: 'The cuff squeezes the arm artery; as it is let down, the doctor listens for the blood to start flowing.', impact: 'It revealed high blood pressure as a major cause of strokes and heart attacks.', f: 'Blood pressure is still measured in millimetres of mercury.', p: M('stethoscope'), x: ['stethoscope'] },
    { id: 'aspirin', n: 'Aspirin', c: 'drug', y: 1897, d: '1897', r: 'Germany', w: 'Felix Hoffmann at Bayer (and Arthur Eichengrün)', s: 'A pain and fever medicine based on willow bark, which people had used for thousands of years.', how: 'It blocks enzymes that make substances causing pain, fever and inflammation, and makes blood less sticky.', impact: 'One of the most used drugs ever; a low dose helps prevent heart attacks in some people.', f: 'Sumerian clay tablets about 4,000 years old mention willow as a remedy.', p: M('pill', '#f4f1ea'), x: ['morphine'] },
    // ---------------- 1900–1949
    { id: 'ecg', n: 'Electrocardiogram (ECG)', c: 'tools', y: 1903, d: '1903', r: 'Leiden, Netherlands', w: 'Willem Einthoven', s: 'A machine that records the heart’s electrical activity as a wavy line.', how: 'Each heartbeat sends an electric signal through the body; skin electrodes pick it up.', impact: 'It shows heart attacks and rhythm problems in minutes.', f: 'Einthoven’s first machine weighed 270 kg and needed five people to run it.', p: M('ecg'), x: ['defibrillator', 'stethoscope'] },
    { id: 'chlorination', n: 'Chlorinated drinking water', c: 'health', y: 1908, d: '1908', r: 'Jersey City, USA', w: 'John Leal', s: 'Adding a little chlorine to drinking water to kill germs.', how: 'Chlorine kills bacteria such as those causing typhoid and cholera.', impact: 'Typhoid deaths fell dramatically; it is one of the great public-health advances of the 20th century.', f: 'Leal was taken to court for adding chlorine — and won.', p: M('water'), x: ['sewers', 'cholera'] },
    { id: 'salvarsan', n: 'Salvarsan — the first “magic bullet”', c: 'drug', y: 1910, d: '1910', r: 'Frankfurt, Germany', w: 'Paul Ehrlich and Sahachiro Hata', s: 'The first modern synthetic drug designed to kill one germ — the bacterium of syphilis — without killing the patient.', how: 'An arsenic compound was chosen after testing hundreds of chemicals on infected animals.', impact: 'It started chemotherapy — the search for chemicals that target disease.', f: 'It was compound number 606.', p: M('vial', '#c9922a'), x: ['syphilis', 'sulfa-drugs'] },
    { id: 'vitamins', n: 'Vitamins', c: 'science', y: 1912, d: '1912', r: 'London and elsewhere', w: 'Casimir Funk; Christiaan Eijkman, Frederick Hopkins', s: 'Scientists discovered that tiny amounts of certain substances in food are needed for health.', how: 'Missing vitamin C causes scurvy, vitamin B1 beriberi, vitamin D rickets.', impact: 'Adding vitamins to foods ended many deficiency diseases.', f: 'Funk named them “vital amines”; when not all turned out to be amines, the e was dropped.', p: M('pill', '#e2a63b'), x: ['scurvy-trial', 'iodised-salt'] },
    { id: 'polio', n: 'Polio', c: 'disease', y: 1916, d: '1916 (big US epidemic)', r: 'Worldwide', w: 'Poliovirus', s: 'A virus that can paralyse, especially children. Summer epidemics terrified parents in the early 1900s.', how: 'It spreads through dirty water and hands, infecting the gut; rarely it attacks nerves in the spine.', impact: 'Vaccines have nearly eradicated it; wild polio now survives in only two countries.', f: 'US President Franklin D. Roosevelt was paralysed by polio, or a similar illness, at 39.', p: M('virus', '#e2a63b'), x: ['polio-vaccine', 'iron-lung'] },
    { id: 'spanish-flu', n: 'Spanish flu', c: 'disease', y: 1918, d: '1918', r: 'Worldwide', w: 'H1N1 influenza virus', s: 'The deadliest flu pandemic, which killed 50 million or more people in two years — more than the First World War.', how: 'It spread with troops and crowded ships. Unusually, it killed many healthy young adults.', impact: 'It led to modern flu surveillance and research.', f: 'It wasn’t from Spain: neutral Spain simply reported it openly while warring countries censored news.', p: M('virus', '#7b1f16'), x: ['flu-vaccine', 'covid-19'] },
    { id: 'bcg', n: 'BCG vaccine (tuberculosis)', c: 'vaccine', y: 1921, d: '1921', r: 'Paris, France', w: 'Albert Calmette and Camille Guérin', s: 'A vaccine made from a weakened cattle TB bacterium, grown for 13 years until it was safe.', how: 'It trains the immune system and protects children especially from severe TB.', impact: 'Still given to over 100 million babies a year.', f: 'Calmette and Guérin re-grew the bacteria 230 times to weaken it.', p: M('syringe', '#2a8fa3'), x: ['tuberculosis'] },
    { id: 'insulin', n: 'Insulin', c: 'drug', y: 1921, d: '1921–1922', r: 'Toronto, Canada', w: 'Frederick Banting, Charles Best, James Collip and John Macleod', s: 'A hormone purified from animal pancreas that turned type 1 diabetes from a death sentence into a treatable condition.', how: 'Insulin lets cells take in sugar from the blood. In type 1 diabetes the body stops making it.', impact: 'In 1922, 14-year-old Leonard Thompson became the first person treated. Millions live full lives with insulin.', f: 'Banting sold the patent for one dollar so insulin would be affordable.', p: M('vial', '#2a8fa3'), x: ['glp1', ['surgery-atlas.html#pancreas-transplant', 'Pancreas transplant']] },
    { id: 'iodised-salt', n: 'Iodised salt', c: 'health', y: 1924, d: '1924', r: 'Michigan, USA (and Switzerland)', w: 'David Murray Cowie and public health officials', s: 'Adding iodine to table salt to prevent goitre and the harm iodine lack does to babies’ brains.', how: 'The thyroid gland needs iodine to make hormones.', impact: 'One of the cheapest and most effective public-health measures ever.', f: 'Goitre was so common in some Alpine valleys that it was seen as normal.', p: M('vial', '#f4f1ea'), x: ['vitamins'] },
    { id: 'iron-lung', n: 'Iron lung', c: 'tools', y: 1928, d: '1928', r: 'Boston, USA', w: 'Philip Drinker and Louis Shaw', s: 'A big metal tank that helped polio patients breathe by changing the air pressure around their body.', how: 'Lowering the pressure inside the tank made the chest expand and pull air in.', impact: 'It saved thousands during polio epidemics. Modern ventilators push air in through a tube instead.', f: 'Paul Alexander lived in an iron lung for over 70 years and became a lawyer.', p: M('ironlung'), x: ['polio', 'intensive-care'] },
    { id: 'penicillin', n: 'Penicillin', c: 'drug', y: 1928, d: '1928 (found); 1941 (first patient)', r: 'London and Oxford, UK', w: 'Alexander Fleming; Howard Florey, Ernst Chain, Norman Heatley', s: 'The first antibiotic, made by a mould, that kills many bacteria.', how: 'It stops bacteria building their cell walls, so they burst.', impact: 'Mass-produced in the USA for D-Day in 1944, it saved millions from infected wounds, pneumonia and syphilis.', f: 'Fleming noticed mould killing bacteria on a dish he had left out while on holiday.', p: M('mold'), x: ['sulfa-drugs', 'streptomycin', 'antibiotic-resistance'] },
    { id: 'sulfa-drugs', n: 'Sulfa drugs', c: 'drug', y: 1935, d: '1935', r: 'Germany', w: 'Gerhard Domagk', s: 'The first antibacterial drugs widely used, made from a red dye called Prontosil.', how: 'They stop bacteria making a vitamin they need to grow.', impact: 'They saved many lives in the years before penicillin was widely available.', f: 'Domagk first tested it on his own daughter, who had a dangerous infection — she recovered.', p: M('pill', '#c0392b'), x: ['penicillin', 'salvarsan'] },
    { id: 'yellow-fever-vaccine', n: 'Yellow fever vaccine (17D)', c: 'vaccine', y: 1937, d: '1937', r: 'New York, USA', w: 'Max Theiler', s: 'A live, weakened vaccine that gives lifelong protection after one dose.', how: 'The virus was grown in mouse and chick tissue until it lost its power to cause disease.', impact: 'Hundreds of millions of doses given; needed for travel to many countries.', f: 'Theiler is the only person to win a Nobel Prize for a virus vaccine (1951).', p: M('syringe', '#e2a63b'), x: ['yellow-fever'] },
    { id: 'dialysis', n: 'Dialysis machine', c: 'tools', y: 1943, d: '1943', r: 'Kampen, Netherlands', w: 'Willem Kolff', s: 'A machine that cleans the blood of people whose kidneys have failed.', how: 'Blood passes along a thin membrane; waste moves out into a cleaning fluid.', impact: 'Millions of people live on dialysis while they wait for a kidney or for life.', f: 'Kolff built his first machine during the German occupation from sausage skins, orange juice cans and a washing machine.', p: M('dialysis'), x: [['surgery-atlas.html#kidney-transplant', 'Kidney transplant']] },
    { id: 'streptomycin', n: 'Streptomycin', c: 'drug', y: 1943, d: '1943', r: 'New Jersey, USA', w: 'Albert Schatz and Selman Waksman', s: 'The first antibiotic that worked against tuberculosis, found in soil bacteria.', how: 'It stops bacteria making proteins.', impact: 'TB sanatoriums closed as patients were cured. Combinations of drugs were needed to stop resistance.', f: 'Waksman won the Nobel Prize; Schatz, the student who found it, had to go to court for credit.', p: M('vial', '#4e9e73'), x: ['tuberculosis', 'controlled-trial'] },
    { id: 'flu-vaccine', n: 'Flu vaccine', c: 'vaccine', y: 1945, d: '1945', r: 'USA', w: 'Thomas Francis and Jonas Salk', s: 'A yearly vaccine against the flu viruses expected to circulate that winter.', how: 'Flu viruses change every year, so experts choose new strains for each season’s vaccine.', impact: 'It prevents millions of illnesses and many deaths, especially in older people.', f: 'It was first used to protect US soldiers in the Second World War.', p: M('syringe', '#2a8fa3'), x: ['spanish-flu'] },
    { id: 'fluoridation', n: 'Water fluoridation', c: 'health', y: 1945, d: '1945', r: 'Grand Rapids, USA', w: 'H. Trendley Dean and others', s: 'Adding a small amount of fluoride to drinking water to prevent tooth decay.', how: 'Fluoride makes tooth enamel more resistant to acid.', impact: 'Childhood tooth decay fell sharply; it remains debated in some places.', f: 'It started after dentists noticed people with naturally fluoride-rich water had stained but strong teeth.', p: M('water'), x: ['chlorination'] },
    { id: 'controlled-trial', n: 'Randomised controlled trial', c: 'science', y: 1948, d: '1948', r: 'UK', w: 'Austin Bradford Hill and the Medical Research Council', s: 'The first modern trial where patients were randomly put into treatment or comparison groups — testing streptomycin for TB.', how: 'Random allocation makes the groups alike, so any difference comes from the treatment.', impact: 'It became the gold standard for testing whether medicines work.', f: 'There was only enough streptomycin for a few patients, which made a fair random choice ethical.', p: M('book'), x: ['scurvy-trial', 'streptomycin'] },
    { id: 'who', n: 'World Health Organization', c: 'health', y: 1948, d: '1948', r: 'Geneva, Switzerland', w: 'United Nations member states', s: 'The UN agency for international public health.', how: 'It coordinates responses to outbreaks, sets standards and supports vaccination programmes.', impact: 'It led the eradication of smallpox and works to end polio, malaria and other diseases.', f: 'Its founding date, 7 April, is World Health Day.', p: M('globe', '#2a8fa3'), x: ['smallpox-eradication', 'nhs'] },
    { id: 'nhs', n: 'Universal health care (NHS)', c: 'health', y: 1948, d: '1948', r: 'United Kingdom', w: 'Aneurin Bevan', s: 'Britain’s National Health Service gave free health care to everyone, paid for by taxes.', how: 'Care is free at the point of use, based on need rather than ability to pay.', impact: 'One of many systems of universal health care now in most rich countries and many others.', f: 'On its first day, doctors were flooded with patients who had never been able to afford a doctor or glasses.', p: M('hospital', '#2b5a8a'), x: ['who'] },
    { id: 'lithium', n: 'Lithium for bipolar disorder', c: 'drug', y: 1949, d: '1949', r: 'Melbourne, Australia', w: 'John Cade', s: 'A simple salt that steadies the extreme mood swings of bipolar disorder.', how: 'How it works is still not fully understood; it affects signalling inside nerve cells.', impact: 'The first effective drug for a serious mental illness, still used today.', f: 'Cade noticed it calmed guinea pigs, then tested it on himself before patients.', p: M('pill', '#8a6cc0'), x: ['chlorpromazine', 'antidepressants'] },
    // ---------------- 1950–1999
    { id: 'smoking-cancer', n: 'Smoking causes cancer', c: 'health', y: 1950, d: '1950', r: 'UK and USA', w: 'Richard Doll and Austin Bradford Hill; Ernst Wynder and Evarts Graham', s: 'Studies of patients proved that smoking causes lung cancer.', how: 'Comparing people with and without lung cancer showed smokers were many times more likely to get it.', impact: 'Smoking rates have fallen in many countries, saving millions of lives, though tobacco still kills about 8 million a year.', f: 'Doll stopped smoking during the study.', p: M('lungs'), x: ['controlled-trial', ['surgery-atlas.html#pneumonectomy', 'Lung removal']] },
    { id: 'intensive-care', n: 'Intensive care and ventilators', c: 'tools', y: 1952, d: '1952', r: 'Copenhagen, Denmark', w: 'Bjørn Ibsen', s: 'During a polio epidemic, students hand-squeezed bags to breathe for patients through a tube — the start of intensive care.', how: 'Ventilators push air into the lungs through a tube; patients are watched closely around the clock.', impact: 'Deaths in the epidemic fell from about 87% to 40%. Every hospital now has an ICU.', f: 'About 1,500 medical students took turns squeezing the bags, day and night, for weeks.', p: M('ecg'), x: ['iron-lung', 'polio'] },
    { id: 'chlorpromazine', n: 'Chlorpromazine (first antipsychotic)', c: 'drug', y: 1952, d: '1952', r: 'Paris, France', w: 'Henri Laborit, Jean Delay and Pierre Deniker', s: 'The first drug that calmed the symptoms of schizophrenia, such as hallucinations.', how: 'It blocks dopamine signals in the brain.', impact: 'Many people left long-stay asylums. Lobotomy was abandoned.', f: 'It was first tried to calm patients before surgery.', p: M('pill', '#8a6cc0'), x: ['lithium', ['surgery-atlas.html#lobotomy', 'Lobotomy']] },
    { id: 'dna', n: 'Structure of DNA', c: 'science', y: 1953, d: '1953', r: 'Cambridge and London, UK', w: 'James Watson, Francis Crick, Rosalind Franklin and Maurice Wilkins', s: 'DNA is a double helix — two strands twisted together, held by pairs of bases.', how: 'Franklin’s X-ray photograph (Photo 51) showed the helix; Watson and Crick built the model.', impact: 'It explained how genes are copied and led to genetic medicine, DNA testing and gene editing.', f: 'Franklin died in 1958 and could not share the 1962 Nobel Prize.', p: M('dna'), x: ['human-genome', 'crispr', ['biology-map.html', 'DNA in Biology Map']] },
    { id: 'polio-vaccine', n: 'Polio vaccines', c: 'vaccine', y: 1955, d: '1955', r: 'USA', w: 'Jonas Salk (injected, 1955); Albert Sabin (drops, 1961)', s: 'Salk’s injected vaccine and Sabin’s oral drops have nearly eradicated polio.', how: 'Salk used killed virus; Sabin used weakened live virus that also stops spread in the gut.', impact: 'Polio cases have fallen by over 99% since 1988.', f: 'Asked who owned the patent, Salk said: “Could you patent the Sun?”', p: M('syringe', '#e2a63b'), x: ['polio', 'who'] },
    { id: 'antidepressants', n: 'Antidepressants', c: 'drug', y: 1957, d: '1957', r: 'Switzerland and USA', w: 'Roland Kuhn (imipramine); later fluoxetine (Prozac, 1987)', s: 'Medicines that can lift severe depression.', how: 'They change the levels of chemical messengers such as serotonin and noradrenaline.', impact: 'With talking therapies, they help many people with depression and anxiety.', f: 'The first ones, imipramine and iproniazid, were found by accident while testing other drugs.', p: M('pill', '#2a8fa3'), x: ['lithium', 'chlorpromazine'] },
    { id: 'ultrasound', n: 'Ultrasound scan', c: 'tools', y: 1958, d: '1958', r: 'Glasgow, UK', w: 'Ian Donald and Tom Brown', s: 'Sound waves too high to hear make pictures of babies in the womb and organs inside the body.', how: 'A probe sends sound pulses and listens for echoes from tissues, building an image.', impact: 'Safe for pregnancy; used for hearts, livers, blood vessels and guiding needles.', f: 'It grew from sonar and an industrial flaw-detector used to check ships’ welds.', p: M('ultrasound'), x: ['x-rays', 'mri'] },
    { id: 'the-pill', n: 'The contraceptive pill', c: 'drug', y: 1960, d: '1960', r: 'USA', w: 'Gregory Pincus, John Rock and Min Chueh Chang; funded by Katharine McCormick, championed by Margaret Sanger', s: 'A daily pill of hormones that prevents pregnancy.', how: 'Hormones stop the ovaries releasing an egg.', impact: 'It gave women far more control over when to have children, changing education and work.', f: 'Early pills had about ten times more hormone than today’s.', p: M('pill', '#c2185b'), x: [['surgery-atlas.html#ivf-retrieval', 'IVF']] },
    { id: 'antibiotic-resistance', n: 'Antibiotic resistance', c: 'disease', y: 1961, d: '1961 (MRSA)', r: 'Worldwide', w: 'Warned of by Alexander Fleming (1945)', s: 'Bacteria evolve to survive antibiotics, making infections harder to treat.', how: 'Each use of antibiotics kills sensitive bacteria and leaves resistant ones to multiply.', impact: 'Drug-resistant infections kill over a million people a year. Using antibiotics only when needed helps.', f: 'In his Nobel speech, Fleming warned that misusing penicillin would breed resistant bacteria.', p: M('bacteria', '#7b1f16'), x: ['penicillin'] },
    { id: 'defibrillator', n: 'Defibrillator', c: 'tools', y: 1965, d: '1947 (first); portable 1965', r: 'USA and Belfast, UK', w: 'Claude Beck; Frank Pantridge (portable)', s: 'A device that gives an electric shock to restart a heart that has stopped beating properly.', how: 'The shock stops chaotic electrical activity so the heart’s own pacemaker can take over.', impact: 'Public defibrillators (AEDs) now hang in stations, shops and schools; anyone can use one by following the voice instructions.', f: 'Pantridge’s first portable one ran on car batteries in an ambulance.', p: M('ecg'), x: ['ecg', ['surgery-atlas.html#pacemaker', 'Pacemaker']] },
    { id: 'measles-vaccine', n: 'Measles and MMR vaccines', c: 'vaccine', y: 1963, d: '1963; MMR 1971', r: 'USA', w: 'John Enders; Maurice Hilleman', s: 'The measles vaccine, later combined with mumps and rubella in one jab (MMR).', how: 'Two doses of weakened live viruses give about 97% protection.', impact: 'Measles vaccination has prevented over 50 million deaths since 2000.', f: 'Hilleman made over 40 vaccines; his mumps vaccine came from his daughter Jeryl Lynn’s throat swab.', p: M('syringe', '#2a8fa3'), x: ['measles'] },
    { id: 'ors', n: 'Oral rehydration solution', c: 'health', y: 1968, d: '1968–1971', r: 'Bangladesh and India', w: 'David Nalin, Richard Cash, Dilip Mahalanabis', s: 'Clean water with the right amounts of salt and sugar, drunk to replace fluid lost in diarrhoea.', how: 'Sugar helps the gut absorb salt and water even during cholera.', impact: 'It has saved tens of millions of children’s lives. The Lancet called it possibly the most important medical advance of the 20th century.', f: 'In 1971 refugee camps, deaths from cholera fell from about 30% to 3%.', p: M('water'), x: ['cholera'] },
    { id: 'ct-scan', n: 'CT scanner', c: 'tools', y: 1971, d: '1971', r: 'London, UK', w: 'Godfrey Hounsfield and Allan Cormack', s: 'A scanner that takes X-rays from many angles and uses a computer to build slices through the body.', how: 'A computer combines hundreds of X-ray views into cross-section images.', impact: 'Doctors could see brain bleeds, tumours and injuries in minutes.', f: 'Hounsfield worked at EMI, the record company — partly funded by Beatles sales.', p: M('scan'), x: ['x-rays', 'mri'] },
    { id: 'artemisinin', n: 'Artemisinin', c: 'drug', y: 1972, d: '1972', r: 'China', w: 'Tu Youyou', s: 'A malaria medicine from sweet wormwood, found by studying ancient Chinese herbal texts.', how: 'It quickly kills malaria parasites in the blood.', impact: 'Combination therapies based on it have saved millions of lives. Tu Youyou won the Nobel Prize in 2015.', f: 'A 4th-century text by Ge Hong said to soak the herb in cold water — the clue to extracting it without heat.', p: M('herb', '#4e9e73'), x: ['malaria', 'quinine'] },
    { id: 'ebola', n: 'Ebola', c: 'disease', y: 1976, d: '1976', r: 'Central and West Africa', w: 'Ebola virus', s: 'A severe virus causing fever and bleeding, spread by contact with body fluids.', how: 'It spreads through blood and fluids of sick people or bodies, so caregivers and funerals were risky.', impact: 'The 2014–2016 West African outbreak killed over 11,000 people. A vaccine (2019) and new treatments now help.', f: 'It is named after the Ebola River in what is now the Democratic Republic of the Congo.', p: M('virus', '#7b1f16'), x: ['ebola-vaccine'] },
    { id: 'mri', n: 'MRI scanner', c: 'tools', y: 1977, d: '1977', r: 'USA and UK', w: 'Raymond Damadian; Paul Lauterbur and Peter Mansfield', s: 'A scanner that uses strong magnets and radio waves to make detailed pictures of soft tissues.', how: 'Hydrogen atoms in water line up in the magnet and send signals that a computer turns into images.', impact: 'Ideal for the brain, spine, joints and many organs, with no X-ray radiation.', f: 'The magnet is about 30,000 times stronger than Earth’s magnetic field.', p: M('scan'), x: ['ct-scan', 'ultrasound'] },
    { id: 'smallpox-eradication', n: 'Smallpox eradicated', c: 'health', y: 1980, d: '1980', r: 'Worldwide', w: 'WHO campaign led by D. A. Henderson, with thousands of health workers', s: 'The first human disease wiped out completely, by vaccination and tracking every case.', how: '“Ring vaccination” vaccinated everyone around each case to stop it spreading.', impact: 'It proved diseases can be eradicated and saves millions of lives every year.', f: 'The last natural case was Ali Maow Maalin, a hospital cook in Somalia, in 1977; he later worked to end polio.', p: M('globe', '#2e7d32'), x: ['smallpox', 'smallpox-vaccine', 'who'] },
    { id: 'ivermectin', n: 'Ivermectin', c: 'drug', y: 1981, d: '1981', r: 'Japan and USA', w: 'Satoshi Ōmura and William Campbell', s: 'A drug from soil bacteria that treats river blindness and other parasitic worms.', how: 'It paralyses the parasites.', impact: 'Donated free since 1987, it has protected hundreds of millions from river blindness. Nobel Prize 2015.', f: 'Ōmura found the bacterium in soil near a golf course in Japan.', p: M('pill', '#4e9e73'), x: ['guinea-worm'] },
    { id: 'hiv', n: 'HIV and AIDS', c: 'disease', y: 1981, d: '1981', r: 'Worldwide', w: 'Virus identified by Françoise Barré-Sinoussi and Luc Montagnier (1983)', s: 'HIV attacks the immune system. Untreated, it leads to AIDS, when the body cannot fight infections.', how: 'It spreads through blood, sex and from mother to baby, not through everyday contact.', impact: 'About 40 million people have died. Medicines now let people with HIV live long lives and not pass it on.', f: '“Undetectable = Untransmittable”: people on effective treatment cannot pass HIV through sex.', p: M('virus', '#c0392b'), x: ['hiv-medicines'] },
    { id: 'hepatitis-b-vaccine', n: 'Hepatitis B vaccine', c: 'vaccine', y: 1981, d: '1981', r: 'USA', w: 'Baruch Blumberg; Maurice Hilleman', s: 'The first vaccine that prevents a cancer — liver cancer caused by hepatitis B.', how: 'It contains a harmless protein from the virus surface; later versions were made by genetically engineered yeast.', impact: 'Given to babies worldwide, it has sharply reduced hepatitis B infections.', f: 'It was the first vaccine made by genetic engineering (1986).', p: M('syringe', '#a0522d'), x: ['hpv-vaccine'] },
    { id: 'h-pylori', n: 'Bacteria cause stomach ulcers', c: 'science', y: 1982, d: '1982', r: 'Perth, Australia', w: 'Barry Marshall and Robin Warren', s: 'They discovered that most stomach ulcers are caused by a bacterium, Helicobacter pylori, not stress.', how: 'The bacterium survives stomach acid and damages the stomach lining.', impact: 'Ulcers are now cured with antibiotics; ulcer surgery became rare.', f: 'To prove it, Marshall drank a culture of the bacteria and got stomach inflammation.', p: M('bacteria', '#c9922a'), x: [['surgery-atlas.html#gastrectomy', 'Stomach surgery']] },
    { id: 'antibody-drugs', n: 'Antibody medicines', c: 'drug', y: 1975, d: '1975 (method); first drug 1986', r: 'Cambridge, UK', w: 'César Milstein and Georges Köhler', s: 'Lab-made antibodies that lock onto one target, used against cancers, arthritis and many other diseases.', how: 'Antibodies recognise one exact shape, such as a protein on cancer cells.', impact: 'Many of the world’s best-selling medicines today are antibodies.', f: 'Milstein and Köhler did not patent their method, so everyone could use it.', p: M('antibody', '#e2a63b'), x: ['imatinib', 'car-t'] },
    { id: 'guinea-worm', n: 'Guinea worm nearly eradicated', c: 'health', y: 1986, d: '1986', r: 'Africa and Asia', w: 'The Carter Center (Jimmy Carter) and partners', s: 'A campaign of clean water, filters and education has nearly wiped out a painful parasite without any medicine or vaccine.', how: 'Filtering drinking water and keeping infected people out of water breaks the worm’s life cycle.', impact: 'Cases fell from about 3.5 million a year in 1986 to fewer than 20.', f: 'It may become the first disease eradicated without a vaccine or cure.', p: M('water'), x: ['smallpox-eradication', 'ivermectin'] },
    { id: 'statins', n: 'Statins', c: 'drug', y: 1987, d: '1987 (first approved)', r: 'Japan and USA', w: 'Akira Endo (discovery, 1973)', s: 'Medicines that lower cholesterol and reduce heart attacks and strokes.', how: 'They block an enzyme the liver uses to make cholesterol.', impact: 'Among the most prescribed drugs in the world.', f: 'Endo tested over 6,000 fungi before finding the first statin in a mould.', p: M('pill', '#f4f1ea'), x: ['aspirin'] },
    { id: 'hiv-medicines', n: 'HIV combination therapy', c: 'drug', y: 1996, d: '1996', r: 'Worldwide', w: 'Many researchers, including David Ho', s: 'Taking three HIV drugs together stops the virus from multiplying and from becoming resistant.', how: 'Different drugs block different steps of the virus’s life cycle.', impact: 'AIDS deaths in rich countries fell sharply; cheap generic drugs later reached millions in Africa. Daily pills (PrEP) can also prevent infection.', f: 'Before 1996, an HIV diagnosis meant death within about 10 years for most people.', p: M('pill', '#c0392b'), x: ['hiv'] },
    // ---------------- 2000–today
    { id: 'imatinib', n: 'Targeted cancer drugs (imatinib)', c: 'drug', y: 2001, d: '2001', r: 'USA and Switzerland', w: 'Brian Druker, Nicholas Lydon and Charles Sawyers', s: 'A pill designed to block the exact faulty protein that drives one type of leukaemia.', how: 'It switches off the overactive enzyme made by an abnormal gene.', impact: 'Chronic myeloid leukaemia changed from usually fatal to a manageable condition. It started the era of targeted therapy.', f: 'It made the cover of TIME magazine as “ammunition for the war on cancer”.', p: M('pill', '#c9922a'), x: ['antibody-drugs', 'car-t'] },
    { id: 'sars', n: 'SARS', c: 'disease', y: 2003, d: '2002–2003', r: 'China, then 29 countries', w: 'SARS coronavirus; alarm raised by Carlo Urbani', s: 'A new coronavirus that spread from Guangdong through travel, infecting about 8,000 people.', how: 'It spread through close contact and droplets; isolation and contact tracing stopped it.', impact: 'It led to new international health rules (2005) and research that later helped against COVID-19.', f: 'Carlo Urbani, the WHO doctor who recognised it, died of it.', p: M('virus', '#c9922a'), x: ['covid-19', 'quarantine'] },
    { id: 'human-genome', n: 'Human Genome Project', c: 'science', y: 2003, d: '2003', r: 'International', w: 'Thousands of scientists in six countries', s: 'The reading of almost all 3 billion letters of human DNA.', how: 'DNA was cut into pieces, read by machines and put back together by computers.', impact: 'It cost about 3 billion dollars; a genome can now be read in a day for a few hundred.', f: 'Humans have only about 20,000 genes — fewer than many scientists expected.', p: M('dna'), x: ['dna', 'crispr'] },
    { id: 'glp1', n: 'GLP-1 medicines', c: 'drug', y: 2005, d: '2005', r: 'USA and Denmark', w: 'John Eng (exenatide); Novo Nordisk and Lotte Bjerre Knudsen (semaglutide)', s: 'Medicines that copy a gut hormone, lowering blood sugar and appetite.', how: 'They boost insulin after meals, slow the stomach and act on hunger centres in the brain.', impact: 'Used for type 2 diabetes and, since the 2020s, for obesity.', f: 'The first came from the saliva of the Gila monster lizard.', p: M('syringe', '#2a8fa3'), x: ['insulin'] },
    { id: 'hpv-vaccine', n: 'HPV vaccine', c: 'vaccine', y: 2006, d: '2006', r: 'Australia and USA', w: 'Ian Frazer and Jian Zhou', s: 'A vaccine against the human papillomavirus, which causes most cervical cancers.', how: 'Virus-like particles with no DNA train the immune system without causing infection.', impact: 'In some countries, cervical cancer in vaccinated young women has fallen by about 90%.', f: 'Scotland has found no cervical cancer in women fully vaccinated at age 12–13.', p: M('syringe', '#c2185b'), x: ['hepatitis-b-vaccine'] },
    { id: 'stem-cells', n: 'Reprogrammed stem cells', c: 'science', y: 2006, d: '2006', r: 'Kyoto, Japan', w: 'Shinya Yamanaka', s: 'Ordinary skin cells were turned back into stem cells able to become any cell type.', how: 'Switching on four genes resets an adult cell’s identity.', impact: 'Used to study diseases and test drugs; early trials use them for eye and brain conditions. Nobel Prize 2012.', f: 'Yamanaka was a surgeon before becoming a scientist.', p: M('cell'), x: ['crispr'] },
    { id: 'crispr', n: 'CRISPR gene editing', c: 'science', y: 2012, d: '2012', r: 'USA and Europe', w: 'Jennifer Doudna and Emmanuelle Charpentier', s: 'A tool that can cut DNA at an exact spot, letting scientists change genes precisely.', how: 'A guide RNA leads the Cas9 protein to a matching DNA sequence, where it cuts.', impact: 'In 2023 the first CRISPR treatment was approved, for sickle cell disease. It also raises big ethical questions.', f: 'CRISPR is a natural defence bacteria use against viruses.', p: M('crispr'), x: ['dna', 'human-genome'] },
    { id: 'hepatitis-c-cure', n: 'Hepatitis C cure', c: 'drug', y: 2013, d: '2013', r: 'USA', w: 'Michael Sofia and others (sofosbuvir); virus found by Harvey Alter, Michael Houghton, Charles Rice', s: 'Pills taken for 8–12 weeks cure over 95% of people with hepatitis C.', how: 'They block enzymes the virus needs to copy itself.', impact: 'A disease that caused liver failure and cancer can now be cured — if people can get the drugs.', f: 'The scientists who discovered the virus won the Nobel Prize in 2020.', p: M('pill', '#c9922a'), x: ['hiv-medicines'] },
    { id: 'car-t', n: 'CAR-T cell therapy', c: 'drug', y: 2017, d: '2017 (approved)', r: 'USA', w: 'Carl June, Michel Sadelain and others', s: 'A patient’s own immune cells are engineered in a lab to find and kill their cancer.', how: 'T cells are given a new receptor (CAR) that recognises the cancer, grown in millions and returned to the patient.', impact: 'It can cure some leukaemias and lymphomas that nothing else could.', f: 'Emily Whitehead, treated in 2012 at age 6, was still cancer-free over a decade later.', p: M('cell'), x: ['antibody-drugs', 'imatinib'] },
    { id: 'ebola-vaccine', n: 'Ebola vaccine', c: 'vaccine', y: 2019, d: '2019', r: 'Canada, then Africa', w: 'Public Health Agency of Canada; Merck', s: 'A vaccine that protects against the deadly Zaire Ebola virus.', how: 'A harmless virus carries an Ebola protein to train the immune system.', impact: 'Ring vaccination helped end outbreaks in the Democratic Republic of the Congo.', f: 'A trial in Guinea in 2015 showed it worked during an outbreak.', p: M('syringe', '#7b1f16'), x: ['ebola'] },
    { id: 'covid-19', n: 'COVID-19 pandemic', c: 'disease', y: 2019, d: '2019', r: 'Worldwide', w: 'SARS-CoV-2 coronavirus', s: 'A new coronavirus that caused a pandemic, with millions of deaths and lockdowns around the world.', how: 'It spreads mainly through the air from infected people, including before they feel ill.', impact: 'It led to the fastest vaccine development in history and changed how people work and learn.', f: 'WHO estimates there were about 7 million reported deaths and many more uncounted.', p: M('virus', '#c0392b'), x: ['mrna-vaccine', 'sars', 'quarantine'] },
    { id: 'mrna-vaccine', n: 'mRNA vaccines', c: 'vaccine', y: 2020, d: '2020', r: 'Germany and USA', w: 'Katalin Karikó and Drew Weissman; BioNTech/Pfizer and Moderna', s: 'Vaccines that give cells instructions to make a harmless virus protein, training the immune system.', how: 'The mRNA is wrapped in a tiny fat bubble; cells read it, make the protein and then break the mRNA down.', impact: 'COVID-19 vaccines were ready in under a year and saved millions of lives. Nobel Prize 2023.', f: 'Karikó worked on mRNA for decades with little funding before it was recognised.', p: M('syringe', '#2a8fa3'), x: ['covid-19', 'smallpox-vaccine'] },
    { id: 'malaria-vaccine', n: 'Malaria vaccines', c: 'vaccine', y: 2021, d: '2021', r: 'Africa', w: 'GSK (RTS,S); University of Oxford and Serum Institute of India (R21, 2023)', s: 'The first vaccines against a parasite, recommended for children in Africa.', how: 'They target the parasite as it enters the blood from a mosquito bite, before it reaches the liver.', impact: 'Rolled out across Africa from 2024, alongside bed nets and medicines.', f: 'RTS,S took over 30 years to develop.', p: M('syringe', '#4e9e73'), x: ['malaria', 'artemisinin'] }
  ];
})();
